"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[6710],{1238(e){e.exports=JSON.parse('{"title":"Lighthouse\ub294 \uadf8\uc800 \uac00\uc774\ub4dc\uc785\ub2c8\ub2e4.","date":"2024-07-24","coverUrl":null,"html":"<h2 data-notion-block-id=\\"8c8bc8d3-faa4-4809-8051-ef616b0f406f\\" id=\\"8c8bc8d3-faa4-4809-8051-ef616b0f406f\\">Lighthouse\ub294 \uadf8\uc800 \uac00\uc774\ub4dc\uc785\ub2c8\ub2e4.</h2><a href=\\"https://blog.sentry.io/how-to-hack-your-google-lighthouse-scores-in-2024/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.sentry.io/how-to-hack-your-google-lighthouse-scores-in-2024/</a><p data-notion-block-id=\\"3e735032-67c7-46ec-ae9b-c1c593110854\\"><b>\uc2ec\uc724\uc12d</b>: Lighthouse\ub294 \uc6f9 \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\uc5d0\uac8c \uc131\ub2a5\uc744 \uce21\uc815\ud558\ub294 \ub3c4\uad6c\ub97c \ub118\uc5b4, \ub192\uc740 \uc810\uc218\ub97c \ubc1b\uc544\uc57c \ud55c\ub2e4\ub294 \uadf8\ub7f0 \uac15\ubc15\ub3c4 \uc0dd\uae30\uac8c \ud558\ub294 \ub3c4\uad6c\uac00 \ub418\uc5c8\uc2b5\ub2c8\ub2e4(\uc800\ub3c4 \uadf8\ub7ac\uad6c\uc694). \uc774 \uae00\uc740 Lighthouse \uc810\uc218\ub97c \uaf3c\uc218\ub85c \ub192\uc774\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud558\uba74\uc11c Lighthouse \uc810\uc218\ub294 \uadf8\uc800 \uac00\uc774\ub4dc\uc774\uba70, \uc0ac\uc6a9\uc131 \ud14c\uc2a4\ud2b8\ub098 \uc131\ub2a5 \uac1c\uc120\uc744 Lighthouse\uc5d0 \uc758\uc874\ud558\uc9c0 \ub9d0\ub77c\ub294 \uae00\uc785\ub2c8\ub2e4. \ubb3c\ub860 Sentry\uc758 \uae00\uc774\uc9c0\ub9cc, \uc131\ub2a5\uc744 \uac1c\uc120\ud560 \ub54c\ub294 Lighthouse\ub9d0\uace0 CrUX\uc640 \uac19\uc740 \uc2e4\uc81c \ub370\uc774\ud130, \ud639\uc740 \uc9c1\uc811 Sentry\uac19\uc740 \ubaa8\ub2c8\ud130\ub9c1 \ud234\uc744 \uc124\uce58\ud574\uc11c \ubb38\uc81c \ubd80\ubd84\uc744 \uc881\ud600\ub098\uac00\ub294 \uac83\uc774 \uc88b\uace0, \ud604\uc7ac\ub294 \uc6f9\ud398\uc774\uc9c0 \uc131\ub2a5 \ub9d0\uace0 \ub2e4\ub978 \uac83\uc5d0 \uc9d1\uc911\ud574\uc57c \ud560 \uc218\ub3c4 \uc788\uc73c\ub2c8 \ud604\uc7ac \uc0c1\ud669\uc5d0 \ub9de\uac8c \uc9c4\ud589\ud558\ub294 \uac83\uc774 \uc88b\uaca0\ub124\uc694. \ubb3c\ub860 Lighthouse\ub97c \ud1b5\ud574 \ubc29\uc9c0\ud558\ub294 \uac83\ub3c4 \uc88b\uc2b5\ub2c8\ub2e4 \ud83d\ude03</p><h2 data-notion-block-id=\\"4333e164-3cd2-4ba0-9ded-9f080a49dec9\\" id=\\"4333e164-3cd2-4ba0-9ded-9f080a49dec9\\">RSC\ub97c \uc0ac\uc6a9\ud558\uba74 \ubcf4\uc548\uc5d0 \ub354 \uc2e0\uacbd\uc368\uc57c \ud55c\ub2e4.</h2><a href=\\"https://www.nodejs-security.com/blog/how-to-protect-against-a-security-breach-in-react-server-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nodejs-security.com/blog/how-to-protect-against-a-security-breach-in-react-server-components</a><p data-notion-block-id=\\"56702ba1-b219-4cc1-a064-634bf479cfce\\"><b>\uc2ec\uc724\uc12d</b>:<b> </b>RSC\uc640 \uc11c\ubc84 \uc561\uc158\uc744 \uc0ac\uc6a9\ud558\uba74 \uc11c\ubc84\uc5d0 \uac12\uc744 \uc804\ub2ec\ud558\ub294 \uac83\uc774\uae30 \ub54c\ubb38\uc5d0, \uc11c\ubc84 \uc561\uc158\uc5d0\uc11c \uac12 \uac80\uc99d\uc774\ub098 \ub370\uc774\ud130 \uc720\ucd9c\uc5d0 \uc2e0\uacbd\uc368\uc57c \ud55c\ub2e4\ub294 \ucc28\uc6d0\uc758 \uae00\uc785\ub2c8\ub2e4. \ud504\ub860\ud2b8\uc5d4\ub4dc\uac00 SSR\uc744 \ub2e4\ub8e8\uac8c \ub418\uba74\uc11c, <a href=\\"https://cheatsheetseries.owasp.org/\\">OWASP \uce58\ud2b8\uc2dc\ud2b8</a>\uc640 \uac19\uc740 \ud544\uc218 \ubcf4\uc548\uc740 \uc2e0\uacbd\uc368\uc57c \ud558\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"c1499555-1312-4ac0-8502-2c4d52d5eba9\\" id=\\"c1499555-1312-4ac0-8502-2c4d52d5eba9\\">INP\ub97c \uac1c\uc120\ud558\uae30 \uc704\ud55c \ud328\ud134</h2><a href=\\"https://kurtextrem.de/posts/improve-inp\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kurtextrem.de/posts/improve-inp</a><p data-notion-block-id=\\"988ff03f-185b-49bc-ab5b-15599134a8c6\\"><b>\uc2ec\uc724\uc12d</b>: <a href=\\"https://ones-to-watch.ethansup.net/news/post/bab36975-b9d2-474a-b5a9-babe0f64cb01#6e09df7f-5435-4f05-9bde-f8c17d5c074c\\">INP\uac00 \ub9d0\ud558\uace0\uc790 \ud558\ub294 \uac83</a>\uc5d0 \uc18c\uac1c\ub41c <code>await-interaction-response</code>\uc640 \uc544\uc9c1 Baseline\uc5d0\uc11c \ubaa8\ub450 \uc9c0\uc6d0\ud558\uc9c0 \uc54a\ub294 Scheduler API\ub97c \ube44\uad50\ud574\uc11c \uc7a5\ub2e8\uc810\uc744 \uc54c\uc544\ubcf4\uace0, INP \uac1c\uc120 \ubc29\ubc95\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4. \ud56d\uc0c1 \uc2e4\ud589\uc2dc\uac04\uc774 \uc9e7\uc740 \uc2a4\ud06c\ub9bd\ud2b8\ub9cc \uc788\uc73c\uba74 \uc88b\uaca0\uc9c0\ub9cc, \uc5ec\ub7ec\uac00\uc9c0 \ubc29\ud574\uc694\uc18c\uac00 \uc788\uc73c\ub2c8 \uae00\uc5d0\uc11c \uc81c\uc2dc\ud574\uc8fc\ub294 \uc5ec\ub7ec \uc635\uc158\uc744 \uace0\ub824\ud558\uc138\uc694. \ud0c0\uc0ac \uc2a4\ud06c\ub9bd\ud2b8\ub97c Worker\uc5d0\uc11c \uac00\uc838\uc624\ub294 <a href=\\"https://partytown.builder.io/\\">PartyTown</a>\uc774\ub098, WebWorker\ub97c \ub354 \uc798 \uc4f8 \uc218 \uc788\uac8c \ud558\ub294 <a href=\\"https://github.com/GoogleChromeLabs/comlink\\">Comlink</a>\uac19\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub3c4 \uac19\uc774\uc694.</p><h2 data-notion-block-id=\\"e30a8dd4-d049-4e68-b98f-ad90947aaefd\\" id=\\"e30a8dd4-d049-4e68-b98f-ad90947aaefd\\">NextJS\uc758 \uce90\uc2dc \uc911\ub3c5</h2><a href=\\"https://zhero-web-sec.github.io/research-and-things/nextjs-and-cache-poisoning-a-quest-for-the-black-hole\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://zhero-web-sec.github.io/research-and-things/nextjs-and-cache-poisoning-a-quest-for-the-black-hole</a><p data-notion-block-id=\\"fb356018-e5d3-41e4-8f3b-8a798ff5dc13\\"><b>\uc2ec\uc724\uc12d</b>: \ud5e4\ub354\uc640 CDN \ub3d9\uc791\uc73c\ub85c \uc624\ub958 \uac12\uc744 \uce90\uc2f1\ud558\uc5ec \uc0ac\uc774\ud2b8 \uc7a5\uc560\ub97c \ubc1c\uc0dd\ud558\ub294 \ubc84\uadf8\ub97c \ucc3e\uc544\ub0b8 \uc0ac\ub840\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. NextJS \ucf54\ub4dc \ub0b4 \uc624\ub958\uc5ec\uc11c \ub9ce\uc740 \uacbd\uc6b0\uc5d0 \uc2e0\uacbd \uc4f0\uae30 \ud798\ub4e0 \ubd80\ubd84\uc774\uc9c0\ub9cc, \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub9cc\ub4e4 \ub54c \uce90\uc2dc \uc911\ub3c5\uacfc CDN \uc124\uc815\uc744 \uc870\uc2ec\ud574\uc57c \uaca0\ub2e4\ub294 \ucc28\uc6d0\uc5d0\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"b59a2921-fad1-4861-8a75-3a046f870f74\\" id=\\"b59a2921-fad1-4861-8a75-3a046f870f74\\">TypeScript\uc5d0\uc11c namespace\ub85c \ucef4\ud3ec\ub10c\ud2b8 \ud0c0\uc785 \ub2e8\uc21c\ud654</h2><a href=\\"https://sergiodxa.com/tutorials/simplify-component-imports-with-typescript-namespaces\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://sergiodxa.com/tutorials/simplify-component-imports-with-typescript-namespaces</a><p data-notion-block-id=\\"fc8901c0-9c34-46a6-86a5-486c2dd76528\\">TypeScript\uc5d0\uc11c \ucef4\ud3ec\ub10c\ud2b8 \ud0c0\uc785\uc744 \ub9cc\ub4e4 \ub54c <code>{\ucef4\ud3ec\ub10c\ud2b8\uc774\ub984}Props</code>\ub85c \uc774\ub984\uc744 \uc815\ud558\uace4 \ud558\ub294\ub370, \uc774\ub97c namespace\ub85c \uc0c1\uc704\ub97c \uc815\uc758\ud574\uc11c \ud0c0\uc785\uc774\ub984\uc744 \ud1b5\uc77c\ud574\uc11c \uc774\ub984 \uc815\ud558\uae30 \uc27d\uac8c \ud558\ub294 \ud301\uc744 \uc804\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"e01f7487-c43f-479e-aba3-8d14d18c00d7\\" id=\\"e01f7487-c43f-479e-aba3-8d14d18c00d7\\">Form Button \uc18d\uc131 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://blog.jim-nielsen.com/2024/all-about-that-button/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.jim-nielsen.com/2024/all-about-that-button/</a><p data-notion-block-id=\\"5d547ea0-e78d-4a28-82f3-5f41010576bb\\">\uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8 \uc5c6\uc774 action\uacfc method, \uadf8\ub9ac\uace0 \ub3d9\uc791\uc744 \uc815\uc758\ud558\ub294 \uc18d\uc131\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc815\ub9d0 \uac04\ub2e8\ud55c \uae00\uc774\ub2c8 \uac00\ubccd\uac8c \ubcf4\uc138\uc694!</p><h2 data-notion-block-id=\\"18c7c378-80e7-4c08-bbe7-2ebf616bdcfd\\" id=\\"18c7c378-80e7-4c08-bbe7-2ebf616bdcfd\\">Code hike beta</h2><a href=\\"https://v1.codehike.org/blog/fine-grained-markdown\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://v1.codehike.org/blog/fine-grained-markdown</a><p data-notion-block-id=\\"a2135256-5454-48f7-bcc6-e2b8611c4e9e\\">\ucf54\ub4dc\uc758 \uc9c4\ud589 \uc0c1\ud669\uc744 \uba4b\uc9c4 \uc560\ub2c8\uba54\uc774\uc158\uacfc \ud568\uaed8 \ubcf4\uc5ec\uc904 \uc218 \uc788\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4. \uba4b\uc838\ubcf4\uc774\ub124\uc694 :)</p>"}')}}]);